/* Morse Code Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"SOS": "save our souls (by folk reading) — Morse ...---...", "CQ": "seek you — Morse -.-. --.-", "73": "best regards — Morse shorthand", "88": "love and kisses — Morse shorthand", "OM": "old man — Morse abbreviation", "YL": "young lady — Morse abbreviation", "W1AW": "The headquarters station of the ARRL, the American Radio Relay League.", "MGY": "The Titanic's wireless callsign, which sent the famous distress calls.", "Callsign structure": "Every callsign joins a national prefix, a digit and a personal suffix: a name in code.", "Vanity callsigns": "Operators choose their own callsigns as personal names on the air."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'SOS';
console.log(lookup(q));

